import type { Token, TokenTree } from './tokens.ts';

export const CSS_HEADER = '/* Generated by packages/tokens. Do not edit. */';

const WIDTH = 90;

// Sole HQ's globals.css opens with this note; it explains the grey roles to anyone who
// reads the generated file.
const ROOT_NOTE =
  "Values come from Sole HQ's design README and brand-and-ux 5.2 to 5.6. Names are shadcn's where shadcn has one. Text greys are split by role: foreground, muted and subtle all clear 4.5:1; faint is for dots, dividers and chevrons only, never words.";

// The theme maps every colour to a Tailwind utility except the sticky note fills, which
// HQ paints through var() on purpose and which need no `bg-sticky-*` class.
const NOT_IN_THEME = /^sticky-(?!foreground$)/;

// The shadow scale Tailwind asks for, each step pointing at one of Sole's two elevations.
const SHADOW_SCALE: ReadonlyArray<readonly [string, string]> = [
  ['xs', 'elevation-sm'],
  ['sm', 'elevation-sm'],
  ['md', 'elevation-lg'],
  ['lg', 'elevation-lg'],
  ['xl', 'elevation-lg'],
];

// Tailwind's radius steps, derived from the one base radius. `xs` is a literal in HQ.
const RADIUS_SCALE: ReadonlyArray<readonly [string, string]> = [
  ['xs', '3px'],
  ['sm', 'calc(var(--radius) - 4px)'],
  ['md', 'calc(var(--radius) - 2px)'],
  ['lg', 'var(--radius)'],
  ['xl', 'calc(var(--radius) + 4px)'],
  ['2xl', 'calc(var(--radius) + 8px)'],
];

// The order of the `--tag-*` mappings in the theme block, as in HQ.
const TAG_THEME_ORDER = ['bg', 'fg', 'border', 'dot'] as const;

function isToken(node: Token | TokenTree | undefined): node is Token {
  return node !== undefined && '$value' in node;
}

function groupOf(tree: TokenTree, name: string): TokenTree {
  const node = tree[name];
  if (node === undefined || isToken(node)) throw new Error(`Could not find the token group "${name}".`);
  return node;
}

function tokenOf(group: TokenTree, name: string): Token {
  const node = group[name];
  if (!isToken(node)) throw new Error(`Could not find the token "${name}".`);
  return node;
}

/** Entries of a group whose children must all be tokens. */
function tokenEntries(group: TokenTree): Array<[string, Token]> {
  return Object.entries(group).map(([name, node]) => {
    if (!isToken(node)) throw new Error(`Expected "${name}" to be a token, not a group.`);
    return [name, node];
  });
}

/** Wraps a sentence as a block comment, with HQ's continuation indent. */
function comment(text: string, indent: string): string[] {
  const words = text.split(/\s+/);
  const rows: string[] = [];
  let row = '';
  for (const word of words) {
    const next = row === '' ? word : `${row} ${word}`;
    if (row !== '' && indent.length + 3 + next.length + 3 > WIDTH) {
      rows.push(row);
      row = word;
    } else {
      row = next;
    }
  }
  rows.push(row);
  return rows.map((text, i) => {
    const open = i === 0 ? `${indent}/* ` : `${indent}   `;
    return i === rows.length - 1 ? `${open}${text} */` : `${open}${text}`;
  });
}

class Lines {
  readonly rows: string[] = [];
  push(...rows: string[]): void {
    this.rows.push(...rows);
  }
  /** One blank line, never two in a row and never at the top. */
  blank(): void {
    if (this.rows.length > 0 && this.rows[this.rows.length - 1] !== '') this.rows.push('');
  }
  /** A declaration, with its description (if any) as a comment above, after a blank line. */
  declare(indent: string, name: string, token: Token, withComment = true): void {
    if (withComment && token.$description !== undefined) {
      this.blank();
      this.push(...comment(token.$description, indent));
    }
    this.push(`${indent}--${name}: ${token.$value};`);
  }
}

export function renderCss(tree: TokenTree): string {
  const color = groupOf(tree, 'color');
  const hue = groupOf(tree, 'hue');
  const radius = groupOf(tree, 'radius');
  const shadow = groupOf(tree, 'shadow');
  const ease = groupOf(tree, 'ease');
  const font = groupOf(tree, 'font');
  const text = groupOf(tree, 'text');
  const out = new Lines();

  out.push(CSS_HEADER, '');
  out.push(...comment(ROOT_NOTE, ''));
  out.push('');

  // :root, in HQ's order.
  out.push(':root {', '  color-scheme: light;');
  out.declare('  ', 'radius', tokenOf(radius, 'base'), false);
  out.blank();
  for (const [name, token] of tokenEntries(color)) out.declare('  ', name, token);
  out.blank();
  for (const [name, token] of tokenEntries(shadow)) out.declare('  ', name, token);
  out.blank();
  out.declare('  ', 'ease-rise', tokenOf(ease, 'rise'));
  out.push('}', '');

  // The hue classes: one line each, as in HQ.
  const hueEntries = Object.entries(hue);
  hueEntries.forEach(([name, node], i) => {
    if (isToken(node)) throw new Error(`Expected hue "${name}" to be a group.`);
    const part = (key: string) => tokenOf(node, key);
    if (i === 0) {
      const note = part('bg').$description;
      if (note !== undefined) out.push(...comment(note, ''));
    }
    out.push(
      `.hue-${name} { --tag-bg: ${part('bg').$value}; --tag-border: ${part('border').$value}; --tag-fg: ${part('fg').$value}; --tag-dot: ${part('dot').$value}; }`,
    );
  });
  out.push('');

  // The Tailwind mapping.
  out.push('@theme inline {');
  out.declare('  ', 'font-sans', tokenOf(font, 'sans'));
  out.declare('  ', 'font-mono', tokenOf(font, 'mono'));
  out.blank();
  for (const [name] of tokenEntries(color)) {
    if (!NOT_IN_THEME.test(name)) out.push(`  --color-${name}: var(--${name});`);
  }
  for (const key of TAG_THEME_ORDER) out.push(`  --color-tag-${key}: var(--tag-${key});`);
  out.blank();

  const radiusNote = tokenOf(radius, 'base').$description;
  if (radiusNote !== undefined) out.push(...comment(radiusNote, '  '));
  for (const [step, value] of RADIUS_SCALE) out.push(`  --radius-${step}: ${value};`);
  out.blank();
  for (const [step, elevation] of SHADOW_SCALE) out.push(`  --shadow-${step}: var(--${elevation});`);
  out.blank();
  out.push('  --ease-rise: var(--ease-rise);');
  out.blank();

  for (const [name, node] of Object.entries(text)) {
    if (name === 'micro') continue;
    if (isToken(node)) throw new Error(`Expected text style "${name}" to be a group.`);
    const size = tokenOf(node, 'size');
    if (size.$description !== undefined) out.push(...comment(size.$description, '  '));
    out.push(`  --text-${name}: ${size.$value};`, `  --text-${name}--line-height: ${tokenOf(node, 'line-height').$value};`);
    const weight = node.weight;
    if (isToken(weight)) out.push(`  --text-${name}--font-weight: ${weight.$value};`);
    const spacing = node['letter-spacing'];
    if (isToken(spacing)) out.push(`  --text-${name}--letter-spacing: ${spacing.$value};`);
  }
  out.push('}', '');

  // text-micro is the one style a theme token cannot express (it uppercases).
  const micro = groupOf(text, 'micro');
  const microSize = tokenOf(micro, 'size');
  if (microSize.$description !== undefined) out.push(...comment(microSize.$description, ''));
  out.push(
    '@utility text-micro {',
    `  font-size: ${microSize.$value};`,
    `  line-height: ${tokenOf(micro, 'line-height').$value};`,
    `  font-weight: ${tokenOf(micro, 'weight').$value};`,
    `  letter-spacing: ${tokenOf(micro, 'letter-spacing').$value};`,
    '  text-transform: uppercase;',
    '}',
  );

  return `${out.rows.join('\n')}\n`;
}

/** DTCG JSON: the token tree as it is (`$schema` is left out on purpose). */
export function renderDtcg(tree: TokenTree): string {
  return `${JSON.stringify(tree, null, 2)}\n`;
}
